const brand = $('Innofresh Brand Brief').first().json;
const video = $('Video Input').first().json;
const transcript = $json;

const transcriptText = transcript.text || (transcript.segments || []).map((s) => `[${s.start}s-${s.end}s] ${s.text}`).join('\n');

const systemPrompt = `คุณเป็นนักคิดคอนเทนต์วิดีโอสั้นให้แบรนด์ "${brand.brandName}"
โทนเสียงแบรนด์: ${brand.toneOfVoice}
กลุ่มเป้าหมาย: ${brand.targetAudience}
คอนเทนต์พิลลาร์: ${brand.contentPillars}
ข้อห้าม: ${brand.forbiddenTopics}
แฮชแท็กหลัก: ${brand.defaultHashtags}

จากบทถอดเสียงวิดีโอที่ให้มา ให้คิดไอเดียคลิปสั้นสำหรับ Reels และ TikTok จำนวน ${brand.numberOfClipIdeas} ไอเดีย โดยแต่ละไอเดียต้องมีฟิลด์ต่อไปนี้:
- platform: "reels" หรือ "tiktok"
- hook: ประโยคเปิด 1-2 วินาทีแรกที่ดึงดูดคนดู
- caption: แคปชั่นโพสต์
- hashtags: แฮชแท็กที่แนะนำ (array of string)
- suggestedStart: เวลาเริ่มตัด (วินาที ตัวเลข)
- suggestedEnd: เวลาจบตัด (วินาที ตัวเลข)
- reason: เหตุผลที่ช่วงนี้น่าสนใจ

ตอบกลับเป็น JSON เท่านั้น ในรูปแบบ {"clips": [ ... ]} ห้ามมีข้อความอื่นนอกเหนือจาก JSON`;

return [{
  json: {
    systemPrompt,
    transcriptText,
    videoTitle: video.videoTitle,
    googleDriveFileId: video.googleDriveFileId,
    brandName: brand.brandName
  }
}];

const source = $('เตรียม Prompt คิดไอเดีย').first().json;
const response = $json;
const content = response.choices[0].message.content;

let parsed;
try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error('AI ไม่ได้ตอบกลับเป็น JSON ที่ถูกต้อง: ' + content);
}

const clips = parsed.clips || [];

return clips.map((clip, index) => ({
  json: {
    clipNumber: index + 1,
    videoTitle: source.videoTitle,
    googleDriveFileId: source.googleDriveFileId,
    brandName: source.brandName,
    platform: clip.platform,
    hook: clip.hook,
    caption: clip.caption,
    hashtags: Array.isArray(clip.hashtags) ? clip.hashtags.join(' ') : clip.hashtags,
    suggestedStart: clip.suggestedStart,
    suggestedEnd: clip.suggestedEnd,
    reason: clip.reason,
    status: 'Needs Review',
    capcutInstructions: `เปิดไฟล์ "${source.videoTitle}" ใน CapCut > ตัดช่วง ${clip.suggestedStart}s-${clip.suggestedEnd}s > ใส่ข้อความ hook ใน 2 วินาทีแรก > ใส่แคปชั่นตามที่แนะนำ แล้วโพสต์ที่ ${clip.platform}`
  }
}));

const source = $('เตรียม Prompt คิดไอเดีย').first().json;
const response = $json;
const content = response.choices[0].message.content;

let parsed;
try {
  parsed = JSON.parse(content);
} catch (error) {
  throw new Error('AI ไม่ได้ตอบกลับเป็น JSON ที่ถูกต้อง: ' + content);
}

const count = (parsed.clips || []).length;

return [{
  json: {
    message: `🎬 มีไอเดียคลิปใหม่ ${count} คลิป สำหรับวิดีโอ "${source.videoTitle}" รอรีวิวใน Google Sheet แล้วครับ`
  }
}];
